using System;
using System.Collections.Generic;
using Vgs.Core;

namespace Vgs.Model
{
    /// <summary>
    /// The arguments of an action: their real type and the caption the game's own dialog uses
    /// (ADR-0052).
    ///
    /// <b>Two sources, and neither is a guess.</b>
    ///
    ///  1. <see cref="ActionParameterTable"/> — generated by
    ///     <c>tools/scan-action-parameters.ps1</c> from the installed assemblies: the types are
    ///     the <c>unbox.any</c> targets of each action's own handler, the captions are the
    ///     <c>MyStringId</c> fields its request method loads. The offline gate re-runs the scan
    ///     and fails when the table no longer matches the game.
    ///  2. <see cref="Verified"/> — the few actions whose types the scan cannot recover (their
    ///     handler converts through an implicit operator rather than an <c>unbox.any</c>), each
    ///     checked by hand against the game and recorded with the command that proves it in
    ///     <c>docs/01-research/api-action-parameters.md</c> §2.2.
    ///
    /// Anything else falls back to the type the game declared — which for the built-in actions is
    /// a placeholder (<c>TypeCode.Empty</c>) and for a third-party action is usually the truth.
    /// That fallback is not silent: <see cref="IsDescribed"/> answers "no", and the screen logs the
    /// action id once, so the coverage of this feature is a fact the log states rather than a
    /// claim the documentation makes (ADR-0052 §4).
    /// </summary>
    public static class ActionParameterHints
    {
        /// <summary>Action id of the programmable block's "run with this argument".</summary>
        public const string RunAction = "Run";

        /// <summary>Action id of the rotor's "rotate to an angle".</summary>
        public const string RotateToAngleAction = "RotateToAngle";

        private static readonly ParameterSpec[] Empty = new ParameterSpec[0];

        /// <summary>
        /// The actions whose argument types are known but not derivable by the scan, verified by
        /// hand. Each entry is one argument's <see cref="TypeCode"/>, in the game's order.
        ///
        /// <b>Why these are not in the generated table.</b> Their handlers hand the argument to a
        /// property setter through an implicit conversion instead of unboxing it, so there is no
        /// <c>unbox.any</c> to read. The type was established by resolving the setter the handler
        /// calls — <c>OnSetVelocityApplied</c> → <c>IMyMotorStator.set_TargetVelocityRPM(Single)</c>
        /// — which is a per-action check, not a general rule.
        /// </summary>
        private static readonly Dictionary<string, TypeCode[]> Verified = BuildVerified();

        private static Dictionary<string, TypeCode[]> BuildVerified()
        {
            var rows = new Dictionary<string, TypeCode[]>(4, StringComparer.Ordinal);

            // Run passes its argument to MyProgrammableBlock.Run(String argument, ...), and the
            // game asks for it with a text dialog (MyGuiScreenDialogText).
            rows["Run"] = new[] { TypeCode.String };

            // These three assign to a float property of the motor, so the argument is a Single
            // even though the metadata declares an empty type.
            rows["SetVelocity"] = new[] { TypeCode.Single };
            rows["SetLowerLimit"] = new[] { TypeCode.Single };
            rows["SetUpperLimit"] = new[] { TypeCode.Single };

            return rows;
        }

        /// <summary>
        /// The specification of every argument of an action, in the game's order.
        ///
        /// The count is <paramref name="declared"/>'s: the game owns the arity, and a table row
        /// longer than that is truncated rather than trusted.
        /// </summary>
        public static ParameterSpec[] For(string actionKey, IList<TypeCode> declared,
                                          VgsLanguage language)
        {
            int count = declared == null ? 0 : declared.Count;
            if (count == 0) return Empty;

            // <b>One field per dialog, not per parameter.</b> The game asks one question per
            // dialog, and a dialog does not always fill one parameter: `SetColor` declares three
            // integers and asks for them with one colour picker. Following the dialogs is what
            // keeps every field's name a name the game actually uses — three fields for the colour
            // would need two invented labels (ADR-0052 §2).
            ActionParameterTable.Row row = ActionParameterTable.Get(actionKey);
            int[] groups = GroupsOf(row, count);
            if (groups == null)
            {
                var plain = new ParameterSpec[count];
                for (int i = 0; i < count; i++)
                {
                    plain[i] = Refine(actionKey, i, At(actionKey, i, declared[i], language));
                }
                return plain;
            }

            var specs = new ParameterSpec[groups.Length];
            int slot = 0;
            for (int g = 0; g < groups.Length; g++)
            {
                ParameterSpec spec = Refine(actionKey, slot, At(actionKey, slot, declared[slot], language));
                if (groups[g] > 1) spec = spec.WithSlots(groups[g]);
                specs[g] = spec;
                slot += groups[g];
            }
            return specs;
        }

        /// <summary>
        /// The dialog sizes for an action, or null when the form should follow the parameters one
        /// for one.
        ///
        /// Null means "no grouping to apply": no row, no captions, or a row whose grouping does not
        /// cover exactly the arguments the game declares. The last case is a table that disagrees
        /// with the game about the arity, and trusting it would drop or duplicate a parameter —
        /// so the parameters win and the table is ignored for shape.
        /// </summary>
        private static int[] GroupsOf(ActionParameterTable.Row row, int count)
        {
            if (row == null || row.GroupSizes == null || row.GroupSizes.Length == 0) return null;

            int total = 0;
            for (int i = 0; i < row.GroupSizes.Length; i++)
            {
                if (row.GroupSizes[i] < 1) return null;
                total += row.GroupSizes[i];
            }
            return total == count ? row.GroupSizes : null;
        }

        /// <summary>
        /// The specification of one argument, without the per-action refinements.
        ///
        /// <b>Private, because refining is not optional.</b> A caller that used this instead of
        /// <see cref="For"/> would get a rotor angle with no range and a direction with no value
        /// list — the window would accept values the action cannot act on, which is the defect
        /// this whole decision exists to prevent (ADR-0052 §3). One entry point, so there is no
        /// wrong one to pick.
        /// </summary>
        private static ParameterSpec At(string actionKey, int index, TypeCode declared,
                                        VgsLanguage language)
        {
            ActionParameterTable.Row row = ActionParameterTable.Get(actionKey);

            TypeCode type = declared;
            string caption = null;

            if (row != null && index >= 0 && index < row.Types.Length)
            {
                type = row.Types[index];
                caption = CaptionOf(row, index, language);
            }
            else
            {
                TypeCode[] verified;
                if (!string.IsNullOrEmpty(actionKey) && Verified.TryGetValue(actionKey, out verified)
                    && index >= 0 && index < verified.Length)
                {
                    type = verified[index];
                }
            }

            return SpecFor(type, caption);
        }

        /// <summary>
        /// True when this action's arguments are described — by the generated table or by a
        /// verified entry. False means the editor is working from the declared type alone, which
        /// for a built-in action is a placeholder; the screen reports that once per action.
        /// </summary>
        public static bool IsDescribed(string actionKey)
        {
            if (string.IsNullOrEmpty(actionKey)) return false;
            if (ActionParameterTable.Get(actionKey) != null) return true;
            return Verified.ContainsKey(actionKey);
        }

        /// <summary>
        /// True when the arguments are described <b>and</b> the type is not the placeholder the
        /// game ships. A row whose derived type is empty is a row that says "this action takes
        /// arguments but I could not learn their type", which is not a description.
        /// </summary>
        public static bool HasKnownTypes(string actionKey)
        {
            ActionParameterTable.Row row = ActionParameterTable.Get(actionKey);
            if (row != null)
            {
                for (int i = 0; i < row.Types.Length; i++)
                {
                    TypeCode code = row.Types[i];
                    if (code == TypeCode.Empty || code == TypeCode.Object) return false;
                }
                return row.Types.Length > 0;
            }

            return Verified.ContainsKey(actionKey);
        }

        /// <summary>Every action id the table describes, for the coverage report and the gate.</summary>
        public static IEnumerable<string> Described
        {
            get { return ActionParameterTable.Ids; }
        }

        private static string CaptionOf(ActionParameterTable.Row row, int index, VgsLanguage language)
        {
            string[] names = language == VgsLanguage.Russian ? row.NamesRu : row.NamesEn;
            if (names == null || index < 0 || index >= names.Length) return null;

            string name = names[index];
            return string.IsNullOrEmpty(name) ? null : name;
        }

        /// <summary>
        /// Turns one argument's type and caption into a specification: the caption becomes the
        /// name, and the caption alone decides the kind of field.
        ///
        /// <b>Nothing about the values is invented here.</b> A caption is a name, not a range: the
        /// editor therefore accepts any value of the right type and lets the action clamp it, and
        /// only the arguments whose allowed values the game itself enumerates (a rotor's
        /// direction) carry a list. That is the honest state of the metadata, and it is why
        /// <see cref="ParameterSpec.HasRange"/> is off unless something verified set it.
        /// </summary>
        private static ParameterSpec SpecFor(TypeCode type, string caption)
        {
            switch (type)
            {
                case TypeCode.Boolean:
                    return ParameterSpec.Text(caption, ParameterDefault.None);

                case TypeCode.Single:
                case TypeCode.Double:
                case TypeCode.Decimal:
                    return ParameterSpec.Typed(type, ParameterKind.Number, caption,
                                               ParameterDefault.None);

                case TypeCode.SByte:
                case TypeCode.Byte:
                case TypeCode.Int16:
                case TypeCode.UInt16:
                case TypeCode.Int32:
                case TypeCode.UInt32:
                case TypeCode.Int64:
                case TypeCode.UInt64:
                    return ParameterSpec.Typed(type, ParameterKind.WholeNumber, caption,
                                               ParameterDefault.None);

                default:
                    return ParameterSpec.Text(caption, ParameterDefault.None);
            }
        }

        /// <summary>
        /// The specification the screen uses for a known action, with the refinements that only
        /// make sense per action: a rotor's angle in degrees bounded the way the game bounds it,
        /// its direction a list of the three values its enum has, its speed a magnitude.
        ///
        /// <b>This is a refinement, not a source of truth.</b> The type and the name still come
        /// from the table; what is added here is what the game's own dialog adds — a range and a
        /// value list — and only where the game's IL shows it (see the research note §2.2–2.4).
        /// </summary>
        public static ParameterSpec Refine(string actionKey, int index, ParameterSpec spec)
        {
            if (spec == null || string.IsNullOrEmpty(actionKey)) return spec;

            if (string.Equals(actionKey, RotateToAngleAction, StringComparison.Ordinal))
            {
                if (index == 0) return spec.WithRange(-360f, 360f).WithDefault("0");
                if (index == 1) return spec.WithRange(0f, float.MaxValue);
                if (index == 2) return spec.AsChoice(new[] { "0", "1", "2" }, new[] { "PARAM_CHOICE_AUTO", "PARAM_CHOICE_CW", "PARAM_CHOICE_CCW" }, "0").WithType(TypeCode.Int64);
            }

            if (string.Equals(actionKey, RunAction, StringComparison.Ordinal) && index == 0)
            {
                return spec.WithDefault(ParameterDefault.ProgrammableBlockArgument);
            }

            if (string.Equals(actionKey, "SetVelocity", StringComparison.Ordinal) && index == 0)
            {
                return spec.WithDefault(ParameterDefault.MotorVelocity);
            }

            if (string.Equals(actionKey, "SetLowerLimit", StringComparison.Ordinal) && index == 0)
            {
                return spec.WithDefault(ParameterDefault.MotorLowerLimit);
            }

            if (string.Equals(actionKey, "SetUpperLimit", StringComparison.Ordinal) && index == 0)
            {
                return spec.WithDefault(ParameterDefault.MotorUpperLimit);
            }

            return spec;
        }
    }
}






